#!/usr/bin/env node
/**
 * Node.js port of dataset/boltons/test6.py.
 *
 * Mirrors the original one-for-one: three required string options parsed with
 * argparse, then an OrderedMultiDict exercised through add/getlist/keys/items.
 */

import { ArgumentParser } from './lib/argparse/index.mjs';
import { SystemExit } from './lib/argparse/errors.mjs';
import { OMD } from './lib/dictutils/index.mjs';
import { list, print, pyStr } from './lib/py/builtins.mjs';

function main() {
  const parser = new ArgumentParser();
  parser.addArgument('--a', { type: pyStr, required: true });
  parser.addArgument('--b', { type: pyStr, required: true });
  parser.addArgument('--c', { type: pyStr, required: true });
  const args = parser.parseArgs();

  const omd = new OMD(); // 创建有序多值字典
  print(omd);
  omd.add(args.a, args.b); // 添加键值对（add方法返回None）
  print(omd);
  omd.add(args.a, args.c); // 添加相同键的第二个值
  print(omd);
  const result1 = omd.getlist(args.a); // 获取键的所有值
  print(result1);
  const result2 = list(omd.keys()); // 获取所有键
  print(result2);
  const result3 = list(omd.items()); // 获取所有键值对
  print(result3);
}

try {
  main();
} catch (error) {
  // argparse signals --help and usage errors the way CPython raises SystemExit.
  if (error instanceof SystemExit) process.exit(error.code);
  throw error;
}

/**
 * Python `repr()` / `str()` reproduction for the value shapes this program
 * prints: `str`, `list` and `tuple`.
 */

import { codePointsOf, hex, isPrintableCodePoint } from './unicode.mjs';

/**
 * Faithful port of CPython's `unicode_repr()`.
 *
 * Quote selection: single quotes normally; double quotes when the string
 * contains a single quote but no double quote (so nothing needs escaping).
 * Then, per code point:
 *   - the active quote and backslash are backslash-escaped
 *   - \t, \n, \r get their short form
 *   - other C0 controls and U+007F become \xhh
 *   - printable code points are emitted literally
 *   - remaining non-printables become \xhh, \uhhhh or \UHHHHHHHH
 */
export function reprStr(text) {
  const quote = text.includes("'") && !text.includes('"') ? '"' : "'";
  let out = quote;
  for (const [ch, cp] of codePointsOf(text)) {
    if (ch === quote || ch === '\\') out += '\\' + ch;
    else if (ch === '\t') out += '\\t';
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (cp < 0x20 || cp === 0x7f) out += '\\x' + hex(cp, 2);
    else if (cp < 0x7f) out += ch;
    else if (isPrintableCodePoint(cp)) out += ch;
    else if (cp <= 0xff) out += '\\x' + hex(cp, 2);
    else if (cp <= 0xffff) out += '\\u' + hex(cp, 4);
    else out += '\\U' + hex(cp, 8);
  }
  return out + quote;
}

/**
 * A Python tuple. Needed as a distinct type because `repr` renders it with
 * parentheses and appends a trailing comma when it holds a single item.
 */
export class PyTuple {
  constructor(items) {
    this.items = items;
  }
  get length() {
    return this.items.length;
  }
  [Symbol.iterator]() {
    return this.items[Symbol.iterator]();
  }
}

export function tuple(...items) {
  return new PyTuple(items);
}

/** Marker interface: any object exposing `__repr__()` renders through it. */
export function repr(value) {
  if (typeof value === 'string') return reprStr(value);
  if (value === null || value === undefined) return 'None';
  if (value === true) return 'True';
  if (value === false) return 'False';
  if (value instanceof PyTuple) {
    if (value.items.length === 1) return '(' + repr(value.items[0]) + ',)';
    return '(' + value.items.map(repr).join(', ') + ')';
  }
  if (Array.isArray(value)) {
    return '[' + value.map(repr).join(', ') + ']';
  }
  if (typeof value === 'object' && typeof value.__repr__ === 'function') {
    return value.__repr__();
  }
  if (typeof value === 'number') return reprNumber(value);
  return String(value);
}

/** `str()` falls back to `repr()` for containers, as in Python. */
export function str(value) {
  if (typeof value === 'string') return value;
  if (typeof value === 'object' && value !== null && typeof value.__str__ === 'function') {
    return value.__str__();
  }
  return repr(value);
}

/** Minimal `repr` for numbers (integers print without a trailing ".0"). */
function reprNumber(value) {
  if (Number.isInteger(value) && Object.is(value, Math.trunc(value))) {
    return String(value);
  }
  return String(value);
}

