export function run(a, b, c) {
  const r = spawnSync('/tmp/dt.sh', ['--a', a, '--b', b, '--c', c], { encoding: 'utf8', maxBuffer: 1 << 28 });
  return { ok: r.status === 0, out: r.stdout };
