export function cps(from, to, filter) {
  const out = [];
  for (let cp = from; cp <= to; cp++) {
    if (cp >= 0xd800 && cp <= 0xdfff) continue;
    if (filter && !filter(cp)) continue;
    out.push(cp);
  }
  return out;
}

export function s(list) { return list.map(cp => String.fromCodePoint(cp)).join(''); }

export function esc(list) { return list.map(cp => '\\U' + cp.toString(16).padStart(8,'0')).join(''); }

// binary search a failing list down to minimal failing single code points
export function isolate(list, place) {
  // test each half
  if (list.length === 1) return list;
  const mid = Math.floor(list.length/2);
  const halves = [list.slice(0,mid), list.slice(mid)];
  let found = [];
  for (const h of halves) {
    const args = ['x','y','z'];
    args[place] = s(h);
    if (!run(args[0],args[1],args[2]).ok) found = found.concat(isolate(h, place));
  }
  if (found.length === 0) return list; // interaction effect, report whole
  return found;
}
